contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address owner, address spender, uint256 amount, uint256 allowanceAmt) public {
        require(amount > allowanceAmt);
        require(allowanceAmt < type(uint256).max);

        // set up: owner holds shares and approves this contract (msg.sender on c) some allowance
        c.transfer(owner, 0); if (__ESBMC_reverted()) return;
        uint256 ownerBalBefore = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        uint256 spenderBalBefore = c.balanceOf(spender); if (__ESBMC_reverted()) return;

        // cannot set allowance for arbitrary owner directly; instead approve from this contract's own balance
        // use owner = address(this) via transfer to self? Instead: approve then transferFrom own shares.
        // Simpler: this contract approves itself for allowanceAmt tokens and attempts transferFrom more.
        bool ok = c.approve(address(this), allowanceAmt); if (__ESBMC_reverted()) return;
        require(ok);
        uint256 selfBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(selfBalBefore < amount || allowanceAmt < amount);

        bool reverted;
        c.transferFrom(address(this), spender, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            c.balanceOf(address(this)) == selfBalBefore &&
            c.balanceOf(spender) == spenderBalBefore &&
            c.balanceOf(owner) == ownerBalBefore &&
            c.allowance(address(this), address(this)) == allowanceAmt
        );
    }
    receive() external payable {}
}

