    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address owner, address spender, uint256 amount, uint256 allowanceAmt) internal {
        vm.assume(amount > allowanceAmt);
        vm.assume(allowanceAmt < type(uint256).max);
        try c.transfer(owner, 0) {} catch { return; }
        uint256 ownerBalBefore;
        try c.balanceOf(owner) returns (uint256 __r) { ownerBalBefore = __r; } catch { return; }
        uint256 spenderBalBefore;
        try c.balanceOf(spender) returns (uint256 __r) { spenderBalBefore = __r; } catch { return; }
        bool ok;
        try c.approve(address(this), allowanceAmt) returns (bool __r) { ok = __r; } catch { return; }
        vm.assume(ok);
        uint256 selfBalBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { selfBalBefore = __r; } catch { return; }
